const o={weekday:"short",day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"};function a(t,n=2){return"₹ "+Number(t||0).toLocaleString("en-IN",{minimumFractionDigits:n,maximumFractionDigits:n})}function i(t){const n=Number(t||0),e=Math.abs(n),r=n<0?"-":"";return e>=1e7?`${r}₹${(e/1e7).toFixed(1)}Cr`:e>=1e5?`${r}₹${(e/1e5).toFixed(1)}L`:e>=1e3?`${r}₹${+(e/1e3).toFixed(1)}K`:`${r}₹${e}`}function u(t){if(!t)return"";const n=Object.fromEntries(new Intl.DateTimeFormat("en-IN",o).formatToParts(new Date(t)).map(e=>[e.type,e.value]));return`${n.weekday}, ${n.day} ${n.month} ${n.year}`}function s(t,n=!0){return t?new Date(t).toLocaleDateString("en-IN",{weekday:n?"long":"short",timeZone:"UTC"}):""}function c(t){return t?new Date(t).toLocaleDateString("en-IN",{day:"2-digit",month:"short",timeZone:"UTC"}):""}function f(t){return new Date(t).toISOString().slice(0,10)}function g(){const t=new Date;return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")}`}function m(){const t=new Date;return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-01`}function d(){const t=new Date().getHours();return t<5?"Good night":t<12?"Good morning":t<17?"Good afternoon":t<21?"Good evening":"Good night"}function h(t=""){return t.charAt(0).toUpperCase()+t.slice(1)}export{i as a,u as b,h as c,g as d,m as e,c as f,d as g,s as h,a as i,f as t};
